import docx
from docx.oxml import parse_xml, OxmlElement
from docx.oxml.ns import qn

doc = docx.Document('/filesystem/Thelbridge_Verification_Memo_Item051_BlockC.docx')
# Check what styles exist:
for s in list(doc.styles._element):
    if s.tag.endswith('style') and s.get(qn('w:styleId')) == 'Title':
        rPr = s.find(qn('w:rPr'))
        if rPr is not None:
            for sz in list(rPr):
                if sz.tag.endswith('sz') or sz.tag.endswith('szCs'):
                    sz.set(qn('w:val'), '20')
for p in doc.paragraphs:
    pPr = p._p.get_or_add_pPr()
    pStyle = pPr.find(qn('w:pStyle'))
    if pStyle is None:
        pStyle = OxmlElement('w:pStyle')
        pPr.insert(0, pStyle)
    pStyle.set(qn('w:val'), 'Normal')
for tbl in doc.tables:
    for row in tbl.rows:
        for cell in row.cells:
            for p in cell.paragraphs:
                pPr = p._p.get_or_add_pPr()
                pStyle = pPr.find(qn('w:pStyle'))
                if pStyle is None:
                    pStyle = OxmlElement('w:pStyle')
                    pPr.insert(0, pStyle)
                pStyle.set(qn('w:val'), 'Normal')
doc.save('/filesystem/Thelbridge_Verification_Memo_Item051_BlockC.docx')
